                    continue
                for sign in (-1, 1):
                    sr, sc = r + sign * dr, c + sign * dc
                    er, ec = r + 2 * sign * dr, c + 2 * sign * dc
                    if not (0 <= sr < h and 0 <= sc < w and 0 <= er < h and 0 <= ec < w):
